351. struct_with_invariants!{
352.     struct Queue<T> {
353.         buffer: Vec<PCell<T>>,
354.         head: AtomicU64<_, FifoQueue::head<T>, _>,
355.         tail: AtomicU64<_, FifoQueue::tail<T>, _>,
356. 
357.         instance: Tracked<FifoQueue::Instance<T>>,
358.     }
359. 
360.     pub closed spec fn wf(&self) -> bool {
361.         predicate {
362.             &&& self.instance@.backing_cells().len() == self.buffer@.len()
363.             &&& forall|i: int| 0 <= i && i < self.buffer@.len() as int ==>
364.                 self.instance@.backing_cells().index(i) ==
365.                     self.buffer@.index(i).id()
366.         }
367. 
368.         invariant on head with (instance) is (v: u64, g: FifoQueue::head<T>) {
369.             &&& g.instance_id() == instance@.id()
370.             &&& g.value() == v as int
371.         }
372. 
373.         invariant on tail with (instance) is (v: u64, g: FifoQueue::tail<T>) {
374.             &&& g.instance_id() == instance@.id()
375.             &&& g.value() == v as int
376.         }
377.     }
378. }
379. 
380. pub struct Producer<T> {
381.     queue: Arc<Queue<T>>,
382.     tail: usize,
383.     producer: Tracked<FifoQueue::producer<T>>,
384. }
385. 
386. impl<T> Producer<T> {
387.     pub closed spec fn wf(&self) -> bool {
388.         (*self.queue).wf()
389.             && self.producer@.instance_id() == (*self.queue).instance@.id()
390.             && self.producer@.value() == ProducerState::Idle(self.tail as nat)
391.             && (self.tail as int) < (*self.queue).buffer@.len()
392.     }
393. }
394. 
395. pub struct Consumer<T> {
396.     queue: Arc<Queue<T>>,
397.     head: usize,
398.     consumer: Tracked<FifoQueue::consumer<T>>,
399. }
400. 
401. impl<T> Consumer<T> {
402.     pub closed spec fn wf(&self) -> bool {
403.         (*self.queue).wf()
404.             && self.consumer@.instance_id() == (*self.queue).instance@.id()
405.             && self.consumer@.value() == ConsumerState::Idle(self.head as nat)
406.             && (self.head as int) < (*self.queue).buffer@.len()
407.     }
408. }
409. 
410. pub fn new_queue<T>(len: usize) -> (pc: (Producer<T>, Consumer<T>))
411.     requires
412.         len > 0,
413.     ensures
414.         pc.0.wf(),
415.         pc.1.wf(),
416. {
417.     let mut backing_cells_vec = Vec::<PCell<T>>::new();
418.     let tracked mut perms = Map::<nat, cell::PointsTo<T>>::tracked_empty();
419.     while backing_cells_vec.len() < len
420.         invariant
421.             forall|j: nat|
422.                 #![trigger( perms.dom().contains(j) )]
423.                 #![trigger( backing_cells_vec@.index(j as int) )]
424.                 #![trigger( perms.index(j) )]
425.                 0 <= j && j < backing_cells_vec.len() as int ==> perms.dom().contains(j)
426.                     && backing_cells_vec@.index(j as int).id() == perms.index(j).id()
427.                     && perms.index(j).is_uninit(),
428.     {
429.         let ghost i = backing_cells_vec.len();
430.         let (cell, cell_perm) = PCell::empty();
431.         backing_cells_vec.push(cell);
432.         proof {
433.             perms.tracked_insert(i as nat, cell_perm.get());
434.         }
435.         assert(perms.dom().contains(i as nat));
436.         assert(backing_cells_vec@.index(i as int).id() == perms.index(i as nat).id());
437.         assert(perms.index(i as nat).is_uninit());
438.     }
439. 
440.     let ghost mut backing_cells_ids = Seq::<CellId>::new(
441.         backing_cells_vec@.len(),
442.         |i: int| backing_cells_vec@.index(i).id(),
443.     );
444.     let tracked (
445.         Tracked(instance),
446.         Tracked(head_token),
447.         Tracked(tail_token),
448.         Tracked(producer_token),
449.         Tracked(consumer_token),
450.     ) = FifoQueue::Instance::initialize(backing_cells_ids, perms, perms);
451.     let tracked_inst: Tracked<FifoQueue::Instance<T>> = Tracked(instance.clone());
452.     let head_atomic = AtomicU64::new(Ghost(tracked_inst), 0, Tracked(head_token));
453.     let tail_atomic = AtomicU64::new(Ghost(tracked_inst), 0, Tracked(tail_token));
454.     let queue = Queue::<T> {
455.         instance: Tracked(instance),
456.         head: head_atomic,
457.         tail: tail_atomic,
458.         buffer: backing_cells_vec,
459.     };
460.     let queue_arc = Arc::new(queue);
461.     let prod = Producer::<T> {
462.         queue: queue_arc.clone(),
463.         tail: 0,
464.         producer: Tracked(producer_token),
465.     };
466.     let cons = Consumer::<T> { queue: queue_arc, head: 0, consumer: Tracked(consumer_token) };
467.     (prod, cons)
468. }
469. 
470. impl<T> Producer<T> {
471.     fn enqueue(&mut self, t: T)
472.         requires
473.             old(self).wf(),
474.         ensures
475.             final(self).wf(),
476.     {
477.         loop
478.             invariant
479.                 self.wf(),
480.         {
481.             let queue = &*self.queue;
482.             let len = queue.buffer.len();
483.             assert(0 <= self.tail && self.tail < len);
484.             let next_tail = if self.tail + 1 == len {
485.                 0
486.             } else {
487.                 self.tail + 1
488.             };
489.             let tracked cell_perm: Option<cell::PointsTo<T>>;
490.             let head =
491.                 atomic_with_ghost!(&queue.head => load();
492.                 returning head;
493.                 ghost head_token => {
494.                 }
495.             );
496.             if head != next_tail as u64 {
497.                 let tracked mut cell_perm = match cell_perm {
498.                     Option::Some(cp) => cp,
499.                     Option::None => {
500.                         assert(false);
501.                         proof_from_false()
502.                     },
503.                 };
504.                 queue.buffer[self.tail].put(Tracked(&mut cell_perm), t);
505.                 atomic_with_ghost!(&queue.tail => store(next_tail as u64); ghost tail_token => {
506.                 });
507.                 self.tail = next_tail;
508.                 return ;
509.             }
510.         }
511.     }
512. }
513. 
514. fn main() {
515. }
516. 
517. }
