                 };
                 queue.buffer[self.tail].put(Tracked(&mut cell_perm), t);
                 atomic_with_ghost!(&queue.tail => store(next_tail as u64); ghost tail_token => {
                 });
                 self.tail = next_tail;
                 return ;
             }
         }
     }
